import numpy as np
from vlb_traj import Session
with Session() as s:
    st=s.state(); obj=st['entities']['contract_law_in_japan']; p=np.array(obj['get_grasped_keypoints'][0]); q=st['robot']['tcp_quaternion_wxyz']
    poses=[[-0.0162,-0.10,1.30],[-0.0162,0.05,1.30],[-0.0162,0.15,1.30],[-0.0162,0.23,1.30],p.tolist()]
    joints=[]
    for xyz in poses:
        r=s.ik(xyz,q); print('IK',xyz,r['success'])
        if not r['success']: raise SystemExit('unreachable')
        joints.append(np.array(r['joint_positions']))
    s.record_start()
    # Move and settle at each waypoint, maintaining open fingers.
    for idx,goal in enumerate(joints):
        for _ in range(45): s.step(np.r_[goal,[0.04,0.04]])
        st=s.state(); print('WAYPOINT',idx,'tcp',st['robot']['tcp_position'],'target',poses[idx])
    print('PREGRASP',s.state()['entities']['contract_law_in_japan'])
    for _ in range(20): s.step(np.r_[joints[-1],[0.0,0.0]])
    print('AFTER_CLOSE',s.state()['entities']['contract_law_in_japan'],s.state()['robot']['tcp_position'])
    lift=s.ik((p+np.array([0,0,0.08])).tolist(),q)
    print('LIFT_IK',lift['success'])
    if lift['success']:
        goal=np.array(lift['joint_positions'])
        for _ in range(60): s.step(np.r_[goal,[0.0,0.0]])
    print('STATUS',s.status())
    actions=s.record_stop(); print('ACTIONS',actions.shape)
    if s.status()['success']:
        s.save_trajectory(actions,'/app/output/trajectory.npz'); print('SAVED')
    else: print('FINAL',s.state()['entities']['contract_law_in_japan'],s.state()['robot'])
